                ldp_bank <= ldbank_e;
                for (s = 0; s < 5; s = s + 1) begin
                    g0 = {AW{1'b0}};
                    g1 = {AW{1'b0}};
                    g2 = {AW{1'b0}};
                    for (k = 0; k < LN; k = k + 1)
                        if (lane_id[k]) begin
                            if (k < G1)      g0 = g0 + ldc_e[(s*LN + k)*AW +: AW];
                            else if (k < G2) g1 = g1 + ldc_e[(s*LN + k)*AW +: AW];
                            else             g2 = g2 + ldc_e[(s*LN + k)*AW +: AW];
                        end
                    ldp_0[s] <= g0;
                    ldp_1[s] <= g1;
                    ldp_2[s] <= g2;
                end
            end
            if (ldp_v) begin
                ldq_bank <= ldp_bank;
                for (s = 0; s < 5; s = s + 1) begin
                    ldq_01[s] <= ldp_0[s] + ldp_1[s];
                    ldq_2[s] <= ldp_2[s];
                end
            end
            if (ldq_v)
                for (s = 0; s < 5; s = s + 1)
                    if (ldq_bank) off1[s] <= ldq_01[s] + ldq_2[s]; else off0[s] <= ldq_01[s] + ldq_2[s];
        end
    end else begin : g_ld3k
        // the same three cycles on keep-prefix adders: a group's (at most 4) masked terms in a two-level tree
        // HBM-KIND8: ldp_v as 11 kept copies (10 q-register enables, 1 for ldq), ldq_v / ldq_bank one pair per stream
        wire [10:0]  ldp_vc;
        wire [9:0]   ldq_vc, ldq_bc;                  // HBM-KIND9: one pair per (stream, AW half) (it3: off0/off1 enables 48)
        wire         ldp_bank;
        for (genvar c = 0; c < 11; c = c + 1) begin : g_ldpv
            ot_su_kffr_k8 u_k (.clk(clk_stage[0]), .rst_n(rst_stage_n[0]), .d(ld_x[15]), .q(ldp_vc[c]));
        end
        for (genvar c = 0; c < 10; c = c + 1) begin : g_ldq
            ot_su_kffr_k8 u_v (.clk(clk_stage[0]), .rst_n(rst_stage_n[0]), .d(ldp_vc[10]), .q(ldq_vc[c]));
            ot_su_kffe_k8 u_b (.clk(clk_stage[0]), .en(ldp_vc[10]), .d(ldp_bank), .q(ldq_bc[c]));
        end
        reg ldp_bank_r;
        always @(posedge clk_stage[0]) if (ld_x[15]) ldp_bank_r <= ldbank_e;
        assign ldp_bank = ldp_bank_r;
        genvar ss, jj, kk;
        wire [5*AW-1:0] s_bus;                         // stream ss's offset, at the third cycle
        integer s;
        always @(posedge clk_stage[0])
            for (s = 0; s < 5; s = s + 1) begin
                if (ldq_vc[2*s]) begin
                    if (ldq_bc[2*s]) off1[s][AW/2-1:0] <= s_bus[s*AW +: AW/2]; else off0[s][AW/2-1:0] <= s_bus[s*AW +: AW/2];
                end
                if (ldq_vc[2*s+1]) begin
                    if (ldq_bc[2*s+1]) off1[s][AW-1:AW/2] <= s_bus[s*AW+AW/2 +: AW-AW/2]; else off0[s][AW-1:AW/2] <= s_bus[s*AW+AW/2 +: AW-AW/2];
                end
            end
        for (ss = 0; ss < 5; ss = ss + 1) begin : g_s
            wire [3*AW-1:0] grp;                       // the three group sums of stream ss
            for (jj = 0; jj < 3; jj = jj + 1) begin : g_j
                localparam integer LO = (jj == 0) ? 0 : (jj == 1) ? G1 : G2;
                localparam integer HI = (jj == 0) ? G1 : (jj == 1) ? G2 : LN;
                wire [4*AW-1:0] t;                     // the group's masked terms, zero-padded to 4
                for (kk = 0; kk < 4; kk = kk + 1) begin : g_t
                    if (LO + kk < HI) begin : g_on
                        assign t[kk*AW +: AW] = lane_id_c[ss*11 + LO + kk] ? ldc_e[(ss*LN + LO + kk)*AW +: AW] : {AW{1'b0}};
                    end else begin : g_off
                        assign t[kk*AW +: AW] = {AW{1'b0}};
                    end
                end
                wire [AW-1:0] s01, s23;
                wire [2:0]    unused_c;
                if (HI - LO > 2) begin : g_4
                    ot_hdc_kadd #(.W(AW), .K(1)) u_a (.a(t[0 +: AW]), .b(t[AW +: AW]), .cin(1'b0), .s(s01), .cout(unused_c[0]));
                    ot_hdc_kadd #(.W(AW), .K(1)) u_b (.a(t[2*AW +: AW]), .b(t[3*AW +: AW]), .cin(1'b0), .s(s23), .cout(unused_c[1]));
                    ot_hdc_kadd #(.W(AW), .K(1)) u_c (.a(s01), .b(s23), .cin(1'b0), .s(grp[jj*AW +: AW]), .cout(unused_c[2]));
                end else if (HI - LO == 2) begin : g_2
                    ot_hdc_kadd #(.W(AW), .K(1)) u_a (.a(t[0 +: AW]), .b(t[AW +: AW]), .cin(1'b0), .s(grp[jj*AW +: AW]), .cout(unused_c[0]));
                    assign {s01, s23, unused_c[2:1]} = 0;
                end else begin : g_1
                    assign grp[jj*AW +: AW] = t[0 +: AW];
                    assign {s01, s23, unused_c} = 0;
                end
            end
            reg  [AW-1:0] p0, p1, p2, q01, q2;
            wire [AW-1:0] s_01, s_all;
            wire [1:0]    unused_q;
            ot_hdc_kadd #(.W(AW), .K(1)) u_q (.a(p0), .b(p1), .cin(1'b0), .s(s_01), .cout(unused_q[0]));
            ot_hdc_kadd #(.W(AW), .K(1)) u_o (.a(q01), .b(q2), .cin(1'b0), .s(s_all), .cout(unused_q[1]));
            assign s_bus[ss*AW +: AW] = s_all;
            always @(posedge clk_stage[0]) begin
                if (ld_x[ss*3 + 0]) p0 <= grp[0 +: AW];
                if (ld_x[ss*3 + 1]) p1 <= grp[AW +: AW];
                if (ld_x[ss*3 + 2]) p2 <= grp[2*AW +: AW];
                if (ldp_vc[2*ss + 0]) q01 <= s_01;
                if (ldp_vc[2*ss + 1]) q2 <= p2;
            end
        end
    end endgenerate

    // ---- F0: liveness, addresses ------------------------------------------------------------------
    wire ol_ge, il_ge;
    ot_hdc_kge #(.W(CW), .K(K)) u_olg (.a(ol_e), .b(no_e), .ge(ol_ge));
    ot_hdc_kge #(.W(CW), .K(K)) u_ilg (.a(il_e), .b(ni_e), .ge(il_ge));
    wire live0 = emit_e && lin_e && !ol_ge && !il_ge;
    // (il << 4) + row[3:0] is the concatenation {il, row[3:0]}
    wire [AW-1:0] kvt, kvt1, vi_sum;
    wire [2:0]    unused_c1;
    ot_hdc_kadd #(.W(AW), .K(K)) u_kv1 (.a(obase_e), .b((row_e >> 4) << KVT_SH), .cin(1'b0), .s(kvt1), .cout(unused_c1[0]));
    ot_hdc_kadd #(.W(AW), .K(K)) u_kv2 (.a(kvt1), .b({il_e[AW-5:0], row_e[3:0]}), .cin(1'b0), .s(kvt), .cout(unused_c1[1]));
    ot_hdc_kadd #(.W(AW), .K(K)) u_via (.a(aibase_e), .b((aind_e == IND_I) ? il_e[AW-1:0] : ol_e[AW-1:0]), .cin(1'b0),
                                        .s(vi_sum), .cout(unused_c1[2]));
    reg          f_v, f_g, f_par;
    reg [AW-1:0] f_a, f_b, f_c, f_d, f_o;
    wire [AW-1:0] f_o_d;                             // HBM-KIND9: (dst_e == DST_KVT) ? kvt : sum_e[4], per AW half
    ot_k9_eqmux_kh #(.W(AW/2), .CW(2), .VAL(DST_KVT)) u_fol (.c(dst_e), .a(kvt[AW/2-1:0]), .b(sum_e[4*AW +: AW/2]), .y(f_o_d[AW/2-1:0]));
    ot_k9_eqmux_kh #(.W(AW-AW/2), .CW(2), .VAL(DST_KVT)) u_foh (.c(dst_e), .a(kvt[AW-1:AW/2]), .b(sum_e[4*AW+AW/2 +: AW-AW/2]), .y(f_o_d[AW-1:AW/2]));
    reg [7:0]    f_src;
    reg          f_cpair;
    always @(posedge clk_stage[0] `OT_SU_ARST(rst_stage_n[0])) begin
        if (!rst_stage_n[0]) begin f_v <= 1'b0; vi_re <= 1'b0; end
        else begin f_v <= live0; vi_re <= live0 && (aind_e != IND_NONE); end
    end
    always @(posedge clk_stage[0]) begin
        f_g <= (aind_e != IND_NONE);
        f_a <= sum_e[0 +: AW];
        f_b <= sum_e[AW +: AW];
        f_c <= sum_e[2*AW +: AW];
        f_d <= sum_e[3*AW +: AW];
        f_o <= f_o_d;
        f_par <= il_e[0];
        f_src <= srcs_e;
        f_cpair <= cpair_e;
        vi_addr <= vi_sum;
    end
    // Pinned SRAM adds two index metadata edges before G1, not an address reinterpretation.
    wire fg_v, fg_g, fg_par, fg_cpair;
    wire [AW-1:0] fg_a, fg_b, fg_c, fg_d, fg_o;
    wire [7:0] fg_src;
    wire [4:0] fg_sh;
    reg [4:0] f_sh;
    always @(posedge clk_stage[0]) f_sh <= gsh_e;
    generate if (FETCH_EXTRA_EDGES > 0) begin:g_index_edge
        reg [FETCH_EXTRA_EDGES-1:0] valid;
        reg [5*AW+15:0] payload[0:FETCH_EXTRA_EDGES-1];
        integer ix;
        always @(posedge clk_stage[0] `OT_SU_ARST(rst_stage_n[0]))
            if (!rst_stage_n[0]) valid <= 0; else valid <= (valid << 1) | f_v;
        always @(posedge clk_stage[0]) begin
            payload[0] <= {f_g,f_par,f_cpair,f_a,f_b,f_c,f_d,f_o,f_src,f_sh};
            for(ix=1;ix<FETCH_EXTRA_EDGES;ix=ix+1)payload[ix]<=payload[ix-1];
        end
        assign fg_v=valid[FETCH_EXTRA_EDGES-1];
        assign {fg_g,fg_par,fg_cpair,fg_a,fg_b,fg_c,fg_d,fg_o,fg_src,fg_sh}=payload[FETCH_EXTRA_EDGES-1];
    end else begin:g_index_direct
        assign {fg_v,fg_g,fg_par,fg_cpair,fg_a,fg_b,fg_c,fg_d,fg_o,fg_src,fg_sh}=
               {f_v,f_g,f_par,f_cpair,f_a,f_b,f_c,f_d,f_o,f_src,f_sh};
    end endgenerate
    // ---- G1, G2: a gathered A (index from the vector memory, scaled by a power of two) ---------------
    reg          g1_v, g2_v, g1_par, g2_par, g1_cpair, g2_cpair;
    reg [AW-1:0] g1_a, g1_b, g1_c, g1_d, g1_o, g2_a, g2_b, g2_c, g2_d, g2_o;
    reg [7:0]    g1_src, g2_src;
    reg [4:0]    g1_sh;
    always @(posedge clk_stage[0] `OT_SU_ARST(rst_stage_n[0])) begin
        if (!rst_stage_n[0]) begin g1_v <= 1'b0; g2_v <= 1'b0; end
        else begin g1_v <= fg_v && fg_g; g2_v <= g1_v; end
    end
    // HBM-KIND8: g2_v copies: [0] A, [1] B, [2] C, [3] D, [4] source + pair, [5] tag
    wire [5:0] g2_vc;
    for (genvar c = 0; c < 6; c = c + 1) begin : g_g2v
        ot_su_kffr_k8 u_k (.clk(clk_stage[0]), .rst_n(rst_stage_n[0]), .d(g1_v), .q(g2_vc[c]));
    end
    wire [AW-1:0] g2_sum;
    wire          unused_c2;
    wire [4:0] g1_sh2;                               // HBM-KIND8: kept copy of g1_sh for the upper half
    ot_su_kff_k8 #(.W(5)) u_g1sh (.clk(clk_stage[0]), .d(fg_sh), .q(g1_sh2));
    wire [AW-1:0] g_shl = vi_q[AW-1:0] << g1_sh, g_shh = vi_q[AW-1:0] << g1_sh2;
    ot_hdc_kadd #(.W(AW), .K(K)) u_g2a (.a(g1_a), .b({g_shh[AW-1:AW/2], g_shl[AW/2-1:0]}), .cin(1'b0), .s(g2_sum), .cout(unused_c2));
    always @(posedge clk_stage[0]) begin
        g1_a <= fg_a; g1_b <= fg_b; g1_c <= fg_c; g1_d <= fg_d; g1_o <= fg_o; g1_par <= fg_par; g1_src <= fg_src;
        g1_cpair <= fg_cpair; g1_sh <= fg_sh;
        g2_a <= g2_sum;
        g2_b <= g1_b; g2_c <= g1_c; g2_d <= g1_d; g2_o <= g1_o; g2_par <= g1_par; g2_src <= g1_src;
        g2_cpair <= g1_cpair;
    end
    // ---- memory reads: the F0 vector, or a gather vector two cycles later ------------------------------
    wire          mr_nv = f_v && !f_g;
    wire          mr_v  = mr_nv || g2_v;
    wire [AW-1:0] mr_a  = g2_vc[0] ? g2_a : f_a;
    wire [AW-1:0] mr_c  = (g2_vc[4] ? g2_cpair : f_cpair) ? (mr_a ^ {{(AW-1){1'b0}}, 1'b1}) : (g2_vc[2] ? g2_c : f_c);
    wire [7:0]    mr_src = g2_vc[4] ? g2_src : f_src;
    assign rd_addr = {g2_vc[3] ? g2_d : f_d, mr_c, g2_vc[1] ? g2_b : f_b, mr_a};
    assign rd_re = {4{mr_v}};
    assign rd_src = mr_src;
    // Exact read-tag extension: x_a..d capture the actual external SRAM q.
    reg m_v, x_v;
    reg [AW-1:0] m_o, x_o;
    reg m_par, x_par;
    wire mf_v, mf_par;
    wire [AW-1:0] mf_o;
    generate if (FETCH_EXTRA_EDGES > 0) begin:g_fetch_edge
        reg [FETCH_EXTRA_EDGES-1:0] v;
        reg [AW:0] tag[0:FETCH_EXTRA_EDGES-1];
        integer fx;
        always @(posedge clk_stage[0] `OT_SU_ARST(rst_stage_n[0]))
            if (!rst_stage_n[0]) v <= 0; else v <= (v << 1) | mr_v;
        always @(posedge clk_stage[0]) begin
            tag[0] <= {g2_vc[5] ? g2_o : f_o, g2_vc[5] ? g2_par : f_par};
            for(fx=1;fx<FETCH_EXTRA_EDGES;fx=fx+1)tag[fx]<=tag[fx-1];
        end
        assign mf_v=v[FETCH_EXTRA_EDGES-1]; assign {mf_o,mf_par}=tag[FETCH_EXTRA_EDGES-1];
    end else begin:g_fetch_direct
        assign mf_v=mr_v;
        assign mf_o=g2_v ? g2_o : f_o;
        assign mf_par=g2_v ? g2_par : f_par;
    end endgenerate
    always @(posedge clk_stage[0] `OT_SU_ARST(rst_stage_n[0])) begin
        if (!rst_stage_n[0]) begin m_v<=0; x_v<=0; end
        else begin m_v<=mf_v; x_v<=m_v; end
    end
    always @(posedge clk_stage[0]) begin
        m_o<=mf_o; m_par<=mf_par; x_o<=m_o; x_par<=m_par;
    end
    generate if (FETCH_EXTRA_EDGES < 0 || FETCH_EXTRA_EDGES > 4) begin:g_bad_fetch
        // 0 raw macro, 2 pinned bank, 4 pinned bank behind a pin-registered lane (ot_hbm_su_static_lane_pinreg)
        ot_su_response_offset_must_be_0_to_4 u_trap();
    end endgenerate
    // ---- X: capture (the memories answered during the cycle before) --------------------------------------
    reg [31:0] x_a, x_b, x_c, x_d;
    always @(posedge clk_stage[0]) begin
        x_a <= rd_q[31:0]; x_b <= rd_q[63:32]; x_c <= rd_q[95:64]; x_d <= rd_q[127:96];
    end
    wire [31:0] x_a2, x_a3, x_c2;                    // HBM-KIND8: kept copies: x_a2 PRE select, x_a3 BF16 candidates, x_c2 lo compare
    ot_su_kff_k8 #(.W(32)) u_xa2 (.clk(clk_stage[0]), .d(rd_q[31:0]), .q(x_a2));
    ot_su_kff_k8 #(.W(32)) u_xa3 (.clk(clk_stage[0]), .d(rd_q[31:0]), .q(x_a3));
    ot_su_kff_k8 #(.W(32)) u_xc2 (.clk(clk_stage[0]), .d(rd_q[95:64]), .q(x_c2));
    // ---- PRE ------------------------------------------------------------------------------------------
    // A' = min(relu(rnd?(A)), imm3), evaluated for the three values rnd?(A) can take (A itself, A truncated to
    // BF16, and truncated + one BF16 ulp) side by side and selected by the rounding decision, so no compare
    // waits for the rounding carry (bit-identical for all inputs: tools/w11_equiv_clip.ys; W11 timing fix)
    wire [31:0] a_t  = {x_a3[31:16], 16'd0};
    wire [15:0] a_hi1;
    ot_hdc_kinc #(.W(16), .K(K)) u_au (.a(x_a3[31:16]), .inc(1'b1), .y(a_hi1));
    wire [31:0] a_u  = {a_hi1, 16'd0};
    wire        a_up = x_a[15] & ((|x_a[14:0]) | x_a[16]);
    // pre_a's compares, as prefix compares: okey(v) <= okey(imm3) for the three candidates, and +0 <= imm3
    // HBM-KIND8: 8 imm3 copies: 0 lex, 1 A select, 2 c_lo, 3 C select, 4 let, 5 leu, 6 le0, 7 clh / clo
    wire [31:0] imm3_0 = cx_imm3_c[0 +: 32], imm3_1 = cx_imm3_c[32 +: 32], imm3_2 = cx_imm3_c[64 +: 32],
                imm3_3 = cx_imm3_c[96 +: 32], imm3_4 = cx_imm3_c[128 +: 32], imm3_5 = cx_imm3_c[160 +: 32],
                imm3_6 = cx_imm3_c[192 +: 32], imm3_7 = cx_imm3_c[224 +: 32];
    wire [31:0] k_imm3 = okey(imm3_0), k_imm3c = okey(imm3_7), k_imm3t = okey(imm3_4), k_imm3u = okey(imm3_5),
                k_imm30 = okey(imm3_6);
    wire        le_x, le_t, le_u, le_0;
    ot_k9_fge #(.K(K)) u_lex (.a(imm3_0), .b(x_a), .ge(le_x));
    ot_k9_fge #(.K(K)) u_let (.a(imm3_4), .b(a_t), .ge(le_t));
    ot_k9_fge #(.K(K)) u_leu (.a(imm3_5), .b(a_u), .ge(le_u));
    ot_k9_fge #(.K(K)) u_le0 (.a(imm3_6), .b(32'h00000000), .ge(le_0));
    wire [31:0] a_mx = pre_a2(x_a2, cx_arelu, cx_amin, imm3_1, le_x, le_0);
    wire [31:0] a_mt = pre_a2(a_t, cx_arelu, cx_amin, imm3_1, le_t, le_0);
    wire [31:0] a_mu = pre_a2(a_u, cx_arelu, cx_amin, imm3_1, le_u, le_0);
    wire [31:0] a_m  = !cx_arnd ? a_mx : a_up ? a_mu : a_mt;
    // clip(C, -imm3, imm3) = fmin(fmax(C, lo), hi) with its three comparisons side by side (bit-identical,
    // ties included: proven by tools/w11_equiv_clip.ys; the chained form was the lane's critical path, W11)
    wire [31:0] c_lo = {1'b1, imm3_2[30:0]};
    wire        c_ge_lo, c_le_hi, c_lohi;
    ot_k9_fge #(.K(K)) u_cgl (.a(x_c2), .b(c_lo), .ge(c_ge_lo));
    ot_k9_fge #(.K(K)) u_clh (.a(imm3_7), .b(x_c), .ge(c_le_hi));
    ot_k9_fge #(.K(K)) u_clo (.a(imm3_7), .b(c_lo), .ge(c_lohi));
    wire [31:0] c_m = !cx_cclip ? x_c : c_ge_lo ? (c_le_hi ? x_c : imm3_3) : (c_lohi ? c_lo : imm3_3);
    reg  [31:0] p_a, p_b, p_c, p_d;
    reg  [AW-1:0] p_o;
    reg         p_v, p_par;
    always @(posedge clk_stage[0] `OT_SU_ARST(rst_stage_n[0])) begin
        if (!rst_stage_n[0]) p_v <= 1'b0; else p_v <= x_v;
    end
    wire [8-1:0] p_vc;                             // HBM-KIND8: kept copies of p_v for the M1 insertion line slices
    for (genvar c = 0; c < 8; c = c + 1) begin : g_pvc
        ot_su_kffr_k8 u_k (.clk(clk_stage[0]), .rst_n(rst_stage_n[0]), .d(x_v), .q(p_vc[c]));
    end
    always @(posedge clk_stage[0]) begin
        p_a <= a_m; p_b <= x_b; p_c <= c_m; p_d <= x_d; p_o <= x_o; p_par <= x_par;
    end
    // ---- M1 ---------------------------------------------------------------------------------------------
    wire p_mul = (cp_m1 == M1_AB) || (cp_m1 == M1_AA) || (cp_m1 == M1_AIMM);
    wire p_div = (cp_m1 == M1_DIVB) || (cp_m1 == M1_DIVIMM);
    wire [31:0] mul1_y, byp1;
    wire f_m1;
    ot_hdc_qmul_lat_k8 #(MLAT) u_m1 (clk_stage[1], rst_stage_n[1], p_v && p_mul, p_a, (cp_m1 == M1_AB) ? p_b : (cp_m1 == M1_AA) ? p_a : cp_imm1,
                      mul1_y, f_m1);
    wire        ba_ge;                               // okey(p_a) >= okey(p_b), i.e. not (okey(p_b) > okey(p_a))
    ot_k9_fge #(.K(K)) u_mxb (.a(p_a), .b(p_b), .ge(ba_ge));
    wire [31:0] byp_in = {(cp_m1_c[5:3] == M1_MAXB && !ba_ge) ? p_b[31:16] : p_a[31:16],   // HBM-KIND9: per-half select copies
                          (cp_m1_c[2:0] == M1_MAXB && !ba_ge) ? p_b[15:0] : p_a[15:0]};
    ot_hdc_delay #(.W(32), .D(MLAT)) u_b1 (.clk(clk_stage[1]), .rst_n(rst_stage_n[1]), .d(byp_in), .q(byp1));
    localparam integer T1W = 32 * 3 + AW + 1;            // B, C', D, O, parity
    wire [T1W-1:0] t1;
    wire           v1;
    wire [31:0]    div1_y;
    wire           f_d1, c1;
    generate
        if (HAS_SFU != 0) begin : g_m1s
            ot_hdc_v41x_fdiv_k8 u_d1 (.clk(clk_stage[1]), .rst_n(rst_stage_n[1]), .v(p_v && p_div), .a(p_a),
                                   .b((cp_m1 == M1_DIVB) ? p_b : cp_imm1), .y(div1_y), .vo(), .fault(f_d1));
            wire [2*8-1:0] l1_sel;
            for (genvar c = 0; c < 8; c = c + 1) begin : g_l1s
                wire dv = (cp_m1_c[3*c +: 3] == M1_DIVB) || (cp_m1_c[3*c +: 3] == M1_DIVIMM);
                assign l1_sel[2*c +: 2] = {dv, !dv};
            end
            ot_hdc_v41x_ins_k8 #(.W(T1W), .K(2), .DEPTHS({H_DIV, H_M}), .DMAX(19)) u_l1 (
                .clk(clk_stage[1]), .rst_n(rst_stage_n[1]), .v(p_vc), .sel(l1_sel), .d({p_b, p_c, p_d, p_o, p_par}),
                .vo(v1), .q(t1), .coll(c1), .busy());
        end else begin : g_m1l
            assign div1_y = 32'd0; assign f_d1 = 1'b0; assign c1 = 1'b0;
            ot_hdc_delay #(.W(T1W), .D(MLAT)) u_t1 (.clk(clk_stage[1]), .rst_n(rst_stage_n[1]), .d({p_b, p_c, p_d, p_o, p_par}), .q(t1));
            wire [MLAT:0] vl;
            ot_hdc_vline #(.D(MLAT)) u_v1 (.clk(clk_stage[1]), .rst_n(rst_stage_n[1]), .v(p_v), .vd(vl));
            assign v1 = vl[MLAT];
        end
    endgenerate
    wire [31:0] m_b = t1[T1W-1 -: 32], m_c = t1[T1W-33 -: 32], m_d = t1[T1W-65 -: 32];
    wire [AW-1:0] m_oa = t1[AW:1];
    wire        m_par1 = t1[0];
    function automatic [15:0] psel(input [2:0] m, input [15:0] d, input [15:0] mu, input [15:0] by);
        psel = (m == M1_DIVB || m == M1_DIVIMM) ? d : (m == M1_AB || m == M1_AA || m == M1_AIMM) ? mu : by;
    endfunction
    wire [31:0] P = {psel(cm_m1_c[5:3], div1_y[31:16], mul1_y[31:16], byp1[31:16]),
                     psel(cm_m1_c[2:0], div1_y[15:0], mul1_y[15:0], byp1[15:0])};
    // ---- M2 and Q -----------------------------------------------------------------------------------------
    wire [31:0] m2_y, q_y, m2_byp;
    wire f_m2, f_q;
    ot_hdc_qmul_lat_k8 #(MLAT) u_m2 (clk_stage[2], rst_stage_n[2], v1 && cm_m2 != M2_BYP, P,
                      {(cm_m2_c[3:2] == M2_C) ? m_c[31:16] : cm_imm1[31:16], (cm_m2_c[1:0] == M2_C) ? m_c[15:0] : cm_imm1[15:0]}, m2_y, f_m2);
    wire qneg = (cm_qm == QM_NEG) || (cm_qm == QM_ALT_NP && !m_par1) || (cm_qm == QM_ALT_PN && m_par1);
    ot_hdc_qmul_lat_k8 #(MLAT) u_q (clk_stage[2], rst_stage_n[2], v1 && cm_qm != QM_OFF, m_c, {m_d[31] ^ qneg, m_d[30:0]}, q_y, f_q);
    wire [31:0] a2_b, a2_c, a2_d;
    wire [AW-1:0] a2_o;
    wire [1:0]  a2_m2;
    ot_hdc_delay #(.W(32 * 4 + AW + 2), .D(MLAT)) u_d2 (.clk(clk_stage[2]), .rst_n(rst_stage_n[2]),
        .d({P, m_b, m_c, m_d, m_oa, cm_m2}), .q({m2_byp, a2_b, a2_c, a2_d, a2_o, a2_m2}));
    wire [MLAT:0] v2l;
    ot_hdc_vline #(.D(MLAT)) u_v2 (.clk(clk_stage[2]), .rst_n(rst_stage_n[2]), .v(v1), .vd(v2l));
    wire v2 = v2l[MLAT];
    wire [31:0] P2;                                  // HBM-KIND9: (a2_m2 == M2_BYP) ? m2_byp : m2_y, per 16-bit half
    ot_k9_eqmux_kh #(.W(16), .CW(2), .VAL(M2_BYP)) u_p2l (.c(a2_m2), .a(m2_byp[15:0]), .b(m2_y[15:0]), .y(P2[15:0]));
    ot_k9_eqmux_kh #(.W(16), .CW(2), .VAL(M2_BYP)) u_p2h (.c(a2_m2), .a(m2_byp[31:16]), .b(m2_y[31:16]), .y(P2[31:16]));
    // ---- AD ------------------------------------------------------------------------------------------------
    reg [31:0] ad_y;
    wire [31:0] nb_b = {~a2_b[31], a2_b[30:0]};
    integer ai;
    always @(*) begin
        for (ai = 0; ai < 4; ai = ai + 1)
            case (ca_ad_c[3*ai +: 3])
                AD_Q:    ad_y[8*ai +: 8] = q_y[8*ai +: 8];
                AD_C:    ad_y[8*ai +: 8] = a2_c[8*ai +: 8];
                AD_NEGB: ad_y[8*ai +: 8] = nb_b[8*ai +: 8];
                AD_IMM:  ad_y[8*ai +: 8] = ca_imm2[8*ai +: 8];
                default: ad_y[8*ai +: 8] = a2_d[8*ai +: 8];
            endcase
    end
    wire [31:0] add_y, add_byp;
    wire f_ad;
    ot_hdc_qadd_lat_k8 #(.KEEP(K), .LAT(ALAT)) u_ad (clk_stage[3], rst_stage_n[3], v2 && ca_ad != AD_BYP, P2, ad_y, add_y, f_ad);
    wire [31:0] r_b, r_c;
    wire [AW-1:0] r_o;
    wire [2:0]  r_ad;
    ot_hdc_delay #(.W(32 * 3 + AW + 3), .D(ALAT)) u_d3 (.clk(clk_stage[3]), .rst_n(rst_stage_n[3]),
        .d({P2, a2_b, a2_c, a2_o, ca_ad}), .q({add_byp, r_b, r_c, r_o, r_ad}));
    wire [ALAT:0] v3l;
    ot_hdc_vline #(.D(ALAT)) u_v3 (.clk(clk_stage[3]), .rst_n(rst_stage_n[3]), .v(v2), .vd(v3l));
    wire v3 = v3l[ALAT];
    wire [8-1:0] v3c;                              // HBM-KIND8: kept copies of v3 for the S insertion line slices
    for (genvar c = 0; c < 8; c = c + 1) begin : g_v3c
        ot_su_kffr_k8 u_k (.clk(clk_stage[3]), .rst_n(rst_stage_n[3]), .d(v3l[ALAT-1]), .q(v3c[c]));
    end
    wire [31:0] R = (r_ad == AD_BYP) ? add_byp : add_y;
    // ---- S --------------------------------------------------------------------------------------------------
    localparam integer T4W = 32 * 3 + AW;                 // R, B, C', O
    wire [T4W-1:0] t4;
    wire           v4, c4;
    wire [31:0]    S;
    wire           f_sfu;
    generate
        if (HAS_SFU != 0) begin : g_sfu
            // sigmoid chain: exp(-R); +1; (1 | R) / that
            wire is_exp = (ci_sfu == SFU_EXP), is_sig = (ci_sfu == SFU_SIGM || ci_sfu == SFU_SILU);
            wire [31:0] y_exp, den, num_d, y_div;
            wire f_e, f_den, f_div;
            wire [D_EXP:0] ve;
            wire [D_EXP:0] vs;                 // a sigmoid-chain element, along the exp
            ot_hdc_vline_k8 #(.D(D_EXP), .R(2)) u_ve (.clk(clk_stage[4]), .rst_n({rst4x[8], rst4x[4]}), .v(v3 && (is_exp || is_sig)), .vd(ve));
            ot_hdc_vline_k8 #(.D(D_EXP), .R(2)) u_vs (.clk(clk_stage[4]), .rst_n({rst4x[9], rst4x[5]}), .v(v3 && is_sig), .vd(vs));
            ot_hdc_v41x_exp_k8 #(.LM(MLAT), .LA(ALAT)) u_exp (.clk(clk_stage[4]), .rst_n(rst4x[0]), .rst_m(rst4x[1]), .rst_a(rst4x[2]), .rst_v(rst4x[7]), .v(v3 && (is_exp || is_sig)),
                                   .x(is_exp ? R : {~R[31], R[30:0]}), .y(y_exp), .vo(), .fault(f_e));
            ot_hdc_qadd_lat_k8 #(.KEEP(K), .LAT(ALAT)) u_den (clk_stage[4], rst4x[6], vs[D_EXP], y_exp, 32'h3F800000, den, f_den);
            wire silu_in = (ci_sfu == SFU_SILU);
            wire [31:0] num_in = silu_in ? R : 32'h3F800000;
            ot_hdc_delay #(.W(32), .D(D_EXP + ALAT)) u_num (.clk(clk_stage[4]), .rst_n(rst_stage_n[4]), .d(num_in), .q(num_d));
            wire [ALAT:0] vdn;
            ot_hdc_vline #(.D(ALAT)) u_vdn (.clk(clk_stage[4]), .rst_n(rst4x[6]), .v(vs[D_EXP]), .vd(vdn));
            ot_hdc_v41x_fdiv_k8 u_div (.clk(clk_stage[4]), .rst_n(rst4x[3]), .v(vdn[ALAT]), .a(num_d), .b(den), .y(y_div), .vo(),
                                    .fault(f_div));
            wire [6:0] sel;
            assign sel = {ci_sfu == SFU_EGATE, ci_sfu == SFU_SPSQRT, ci_sfu == SFU_SQRT, ci_sfu == SFU_RSQRT,
                          is_sig, is_exp, ci_sfu == SFU_NONE};
            wire [7*8-1:0] l4_sel;
            for (genvar c = 0; c < 8; c = c + 1) begin : g_l4s
                wire [2:0] cf = ci_sfu_c[3*c +: 3];
                assign l4_sel[7*c +: 7] = {cf == SFU_EGATE, cf == SFU_SPSQRT, cf == SFU_SQRT, cf == SFU_RSQRT,
                                           cf == SFU_SIGM || cf == SFU_SILU, cf == SFU_EXP, cf == SFU_NONE};
            end
            wire [3*8-1:0] l4_sel3;
            for (genvar c = 0; c < 8; c = c + 1) begin : g_l4t
                assign l4_sel3[3*c +: 3] = l4_sel[7*c +: 3];
            end
            if (FULL != 0) begin : g_full
                ot_hbm_su_static_ins_k8 #(.W(T4W), .K(7),
                    .DEPTHS({H_EG, H_SP, H_SQRT, H_RSQ, H_SIG, H_EXP, 16'd0}), .DMAX(D_SP)) u_l4 (
                    .clk(clk_insert), .rst_n(rst_n),
`ifdef OT_SU_SYNC_RST
                    .rst_regions_n(rst_insert_n),
`endif
                    .v(v3c), .sel(l4_sel), .d({R, r_b, r_c, r_o}), .vo(v4), .q(t4), .coll(c4), .busy());
            end else begin : g_vec
                ot_hbm_su_static_ins_k8 #(.W(T4W), .K(3), .DEPTHS({H_SIG, H_EXP, 16'd0}), .DMAX(D_SIG)) u_l4 (
                    .clk(clk_insert), .rst_n(rst_n),
`ifdef OT_SU_SYNC_RST
                    .rst_regions_n(rst_insert_n),
`endif
                    .v(v3c), .sel(l4_sel3), .d({R, r_b, r_c, r_o}), .vo(v4), .q(t4),
                    .coll(c4), .busy());
            end
            function automatic [15:0] ssel(input [2:0] c, input [15:0] e, input [15:0] dv, input [15:0] t, input [15:0] sd);
                ssel = (c == SFU_EXP) ? e : (c == SFU_SIGM || c == SFU_SILU) ? dv : (c == SFU_NONE) ? t : sd;
            endfunction
            wire [31:0] t4r = t4[T4W-1 -: 32];
            assign S = {ssel(cs_sfu_c[5:3], y_exp[31:16], y_div[31:16], t4r[31:16], side_y[31:16]),
                        ssel(cs_sfu_c[2:0], y_exp[15:0], y_div[15:0], t4r[15:0], side_y[15:0])};
            assign f_sfu = f_e | f_den | f_div;
        end else begin : g_nosfu
            assign t4 = {R, r_b, r_c, r_o}; assign v4 = v3; assign c4 = 1'b0;
            assign S = R; assign f_sfu = 1'b0;
        end
    endgenerate
    assign side_v = (FULL != 0) && v3 && (ci_sfu == SFU_RSQRT || ci_sfu == SFU_SQRT || ci_sfu == SFU_SPSQRT ||
                                          ci_sfu == SFU_EGATE);
    assign side_x = R;
    wire [31:0] s_b = t4[T4W-33 -: 32], s_c = t4[T4W-65 -: 32];
    wire [AW-1:0] s_o = t4[AW-1:0];
    // ---- E1 -------------------------------------------------------------------------------------------------
    wire [31:0] e1m, e1a, e1_byp;
    wire f_e1m, f_e1a;
    ot_hdc_qmul_lat_k8 #(MLAT) u_e1m (clk_stage[5], rst_stage_n[5], v4 && (cs_e1 == E1_MULC || cs_e1 == E1_MULIMM), S,
                       (cs_e1 == E1_MULC) ? s_c : cs_imm2, e1m, f_e1m);
    wire [31:0] e1a3;
    ot_hdc_qadd_lat_k8 #(.KEEP(K), .LAT(ALAT)) u_e1a (clk_stage[5], rst_stage_n[5], v4 && (cs_e1 == E1_ADDC || cs_e1 == E1_ADDIMM), S,
                       (cs_e1 == E1_ADDC) ? s_c : cs_imm2, e1a3, f_e1a);
    // E1 is MLAT deep (its multiply); the 3-cycle add waits MLAT - 3 more
    ot_hdc_delay #(.W(32), .D(MLAT - ALAT)) u_e1ad (.clk(clk_stage[5]), .rst_n(rst_stage_n[5]), .d(e1a3), .q(e1a));
    wire [31:0] e_b;
    wire [AW-1:0] e_o;
    wire [2:0]  e_e1;
    ot_hdc_delay #(.W(32 * 2 + AW + 3), .D(MLAT)) u_d5 (.clk(clk_stage[5]), .rst_n(rst_stage_n[5]), .d({S, s_b, s_o, cs_e1_c[2:0]}),
                                                   .q({e1_byp, e_b, e_o, e_e1}));
    wire [2:0] e_e1h;                                // HBM-KIND8: second E1 code line for the upper half of T
    ot_hdc_delay #(.W(3), .D(MLAT)) u_d5h (.clk(clk_stage[5]), .rst_n(rst_stage_n[5]), .d(cs_e1_c[5:3]), .q(e_e1h));
    wire [MLAT:0] v5l;
    ot_hdc_vline #(.D(MLAT)) u_v5 (.clk(clk_stage[5]), .rst_n(rst_stage_n[5]), .v(v4), .vd(v5l));
    wire v5 = v5l[MLAT];
    function automatic [15:0] tsel(input [2:0] c, input [15:0] m, input [15:0] a, input [15:0] b);
        tsel = (c == E1_MULC || c == E1_MULIMM) ? m : (c == E1_ADDC || c == E1_ADDIMM) ? a : b;
    endfunction
    wire [31:0] T = {tsel(e_e1h, e1m[31:16], e1a[31:16], e1_byp[31:16]), tsel(e_e1, e1m[15:0], e1a[15:0], e1_byp[15:0])};
    // ---- E2 ---------------------------------------------------------------------------------------------------
    wire [31:0] e2m, e2_byp;
    wire f_e2;
    ot_hdc_qmul_lat_k8 #(MLAT) u_me2 (clk_stage[6], rst_stage_n[6], v5 && ce_e2 != E2_BYP, T, {(ce_e2_c[3:2] == E2_MULB) ? e_b[31:16] : ce_imm1[31:16], (ce_e2_c[1:0] == E2_MULB) ? e_b[15:0] : ce_imm1[15:0]}, e2m, f_e2);
    wire [AW-1:0] u_o;
    wire [1:0]  u_e2;
    ot_hdc_delay #(.W(32 + AW + 2), .D(MLAT)) u_d6 (.clk(clk_stage[6]), .rst_n(rst_stage_n[6]), .d({T, e_o, ce_e2}),
                                               .q({e2_byp, u_o, u_e2}));
    wire [MLAT:0] v6l;
    ot_hdc_vline #(.D(MLAT)) u_v6 (.clk(clk_stage[6]), .rst_n(rst_stage_n[6]), .v(v5), .vd(v6l));
    wire v6 = v6l[MLAT];
    wire [31:0] U = (u_e2 == E2_BYP) ? e2_byp : e2m;
    // ---- OUT --------------------------------------------------------------------------------------------------
    // bf16(U) = (U[31:16] + inc) << 16, inc = U[15] & (U[16] | U[14:0] != 0): round to nearest even.  The KV
    // write is bf16(out) = bf16(U) whether or not out was rounded (bf16 of a BF16 value is itself)
    wire [15:0] u_hi1;
    ot_hdc_kinc #(.W(16), .K(K)) u_rnd (.a(U[31:16]), .inc(U[15] & (U[16] | (|U[14:0]))), .y(u_hi1));
    wire [31:0] u_bf = {u_hi1, 16'd0};
    wire [31:0] out = {co_rnd_c[1] ? u_bf[31:16] : U[31:16], co_rnd_c[0] ? u_bf[15:0] : U[15:0]};
    reg         ov_r;
    reg  [31:0] o_x;
    always @(posedge clk_stage[7] `OT_SU_ARST(rst_stage_n[7])) begin
        if (!rst_stage_n[7]) begin vm_we <= 1'b0; kv_we <= 1'b0; ov_r <= 1'b0; end
        else begin
            vm_we <= v6 && co_dst == DST_VM;
            kv_we <= v6 && (co_dst == DST_KV || co_dst == DST_KVT);
            ov_r <= v6;
        end
    end
    always @(posedge clk_stage[7]) begin
        vm_waddr <= u_o; vm_wdata <= out;
        kv_waddr <= u_o; kv_wdata <= u_bf;
        o_x <= out;
    end
    assign ro_v = ov_r;
    assign ro_x = o_x;
    // ---- status ---------------------------------------------------------------------------------------------------
    reg fault_r;
    always @(posedge clk_stage[7] `OT_SU_ARST(rst_stage_n[7])) begin
        if (!rst_stage_n[7]) fault_r <= 1'b0;
        else fault_r <= f_m1 | f_d1 | f_m2 | f_q | f_ad | f_sfu | f_e1m | f_e1a | f_e2;
    end
    assign fault = fault_r;
    assign coll = c1 | c4;
endmodule

// HBM-KIND8 kept same-edge register copies; HBM-KIND9: each copy is an ot_k9_fam copy family (3 identical members per bit,
// loads balanced <= 32 by the kit's ot_rst_copies splitter; it3 census: single copies drove up to 84 loads)
module ot_su_kff_k8 #(parameter integer W = 1) (input wire clk, input wire [W-1:0] d, output wire [W-1:0] q);
    ot_k9_fam #(.W(W), .N(3)) u_f (.clk(clk), .d(d), .q(q));
endmodule
// HBM-KIND9: reset copies as ot_k9_famr copy families (it3: ldp_v / g2_v copies 48 loads)
module ot_su_kffr_k8 #(parameter integer W = 1) (input wire clk, input wire rst_n, input wire [W-1:0] d, output wire [W-1:0] q);
    ot_k9_famr #(.W(W), .N(3)) u_f (.clk(clk), .rst_n(rst_n), .d(d), .q(q));
endmodule
// one kept copy of an enabled register (q <= en ? d : q)
(* keep_hierarchy = "yes" *)
module ot_su_kffe_k8 #(parameter integer W = 1) (input wire clk, input wire en, input wire [W-1:0] d, output wire [W-1:0] q);
    (* keep = 1 *) reg [W-1:0] r;
    always @(posedge clk) if (en) r <= d;
    assign q = r;
endmodule
